  'wy.cr2': 'Trade setup analysis', 'wy.cg2': 'Mostly Manual',
  'wy.cr3': 'Entry & exit planning', 'wy.cg3': 'Mostly Manual',
  'wy.cr4': 'Stop-loss & take-profit planning', 'wy.cg4': 'Separate Tools',
