  'at.h1a': 'Your AI trading assistant', 'at.h1b': 'for smarter decisions.',
  'at.heroBody': 'Fragmented charts, endless news feeds, and hours of manual analysis - replaced by one assistant. Tradvio AI watches your markets, spots the setups, and delivers structured trade plans with confidence scores.',
  'at.cta1': 'Start Trading Smarter', 'at.cta2': 'How it works',
  'at.check1': 'Auto Chart Analysis', 'at.check2': 'AI-Powered Signals', 'at.check3': 'Risk Management', 'at.check4': '24/7 Monitoring',
  'at.cardTitle': 'AI Assistant', 'at.active': 'ACTIVE',
