const STRATEGY_KEYS: Record<string, string> = {
  'Cup & Handle': 'st.cupHandle', 'Gap-and-Go': 'st.gapGo', 'Head & Shoulders': 'st.headShoulders',
  'Relative Strength': 'st.relStrength', 'Liquidity Sweep': 'st.liqSweep', 'Fair Value Gap': 'st.fvg',
  'BOS / CHoCH': 'st.bosChoch', 'Asian-London Range': 'st.asianLondon', 'Order Block': 'st.orderBlock',
  'Falling Wedge': 'st.fallingWedge', 'Funding & OI': 'st.fundingOi', 'Wyckoff': 'st.wyckoff',
  'Double Tops/Bottoms': 'st.doubleTop', 'Volume Spread': 'st.volumeSpread', 'Triangle Break': 'st.triangleBreak',
  'MTF Confluence': 'st.mtfConfluence', 'Seasonality': 'st.seasonality', 'Harmonics': 'st.harmonics',
  'Trendline Break': 'st.trendline', 'COT Divergence': 'st.cotDiv', 'Sector Rotation': 'st.sectorRot',
  'NR7 Squeeze': 'st.nr7Squeeze', 'Hidden Divergence': 'st.hiddenDiv', 'Elliott Wave': 'st.elliott',
};

/** Translate an agent market name (e.g. "Stocks") using the current language. */
export function marketLabel(m: string, t: (key: string) => string): string {
  return t(MARKET_KEYS[m] ?? '');
}

/** Translate an agent short strategy (e.g. "Cup & Handle") using the current language. */
export function strategyLabel(st: string, t: (key: string) => string): string {
  return t(STRATEGY_KEYS[st] ?? '');
}

export function resolvePath(path: string, lang: Language): string {
  // First try the current language.
  const map = SLUGS[lang] ?? {};
  for (const [enPath, locPath] of Object.entries(map)) {
    if (locPath === path) return enPath;
  }
  // Fall back to scanning every language so localized URLs work even
  // when the stored language preference is different (e.g. a shared link).
  for (const otherMap of Object.values(SLUGS)) {
    if (otherMap === map) continue;
    for (const [enPath, locPath] of Object.entries(otherMap)) {
      if (locPath === path) return enPath;
    }
  }
  return path;
}

const dicts: Record<Language, Dict> = { en, it, de, fr, es };

/* ─── Context ───────────────────────────────────────── */
interface LanguageContextValue {
  lang: Language;
  setLang: (lang: Language) => void;
  t: (key: string) => string;
}

const LanguageContext = createContext<LanguageContextValue>({
  lang: 'en',
  setLang: () => {},
  t: (key) => en[key] ?? key,
});

const STORAGE_KEY = 'tradvio-lang';

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Language>(() => {
    if (typeof window === 'undefined') return 'en';
    const saved = window.localStorage.getItem(STORAGE_KEY);
    return (saved === 'it' || saved === 'de' || saved === 'fr' || saved === 'es') ? saved : 'en';
  });

  const setLang = (next: Language) => {
    setLangState(next);
    try { window.localStorage.setItem(STORAGE_KEY, next); } catch { /* private mode */ }
    // Sync the current URL slug with the selected language
    // (e.g. /ai-trading-platform/ → /piattaforma-trading-ai/ for Italian).
    try {
      const current = window.location.pathname;
      const enPath = resolvePath(current, lang);
      const newPath = localizePath(enPath, next);
      if (newPath !== current) {
        window.history.replaceState(null, '', newPath);
      }
    } catch { /* SSR guard */ }
  };

  useEffect(() => {
    document.documentElement.lang = lang;
  }, [lang]);

  const t = (key: string) => dicts[lang][key] ?? en[key] ?? key;

  return (
    <LanguageContext.Provider value={{ lang, setLang, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  return useContext(LanguageContext);
}
